mapper.select:
select id, entrust_mix_area, entrusted_mix_area, glue, create_by, create_time, update_by, update_time, del_flag,
remark from t_glue_span_setting
where del_flag = '0'
and entrust_mix_area = #{entrustMixArea}
and entrusted_mix_area = #{entrustedMixArea}

and INSTR(glue, #{glue}) > 0

    order by create_time desc


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.entrustMixArea,jdbcType=VARCHAR} entrust_mix_area, #{data.entrustedMixArea,jdbcType=VARCHAR} entrusted_mix_area, #{data.glue,jdbcType=VARCHAR} glue
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_span_setting m inner join temp_table t on m.entrust_mix_area = t.entrust_mix_area and m.glue = t.glue and m.del_flag ='0'

mapper.insert:
insert into t_glue_span_setting (id,entrust_mix_area,entrusted_mix_area,glue,create_by,create_time,update_by,update_time,del_flag,remark ) select NULL id, x.* from (
select #{glueSpanSetting.entrustMixArea,jdbcType=VARCHAR} entrust_mix_area, #{glueSpanSetting.entrustedMixArea,jdbcType=VARCHAR} entrusted_mix_area, #{glueSpanSetting.glue,jdbcType=VARCHAR} glue, #{glueSpanSetting.createBy,jdbcType=VARCHAR} create_by, #{glueSpanSetting.createTime,jdbcType=TIMESTAMP} create_time, #{glueSpanSetting.updateBy,jdbcType=VARCHAR} update_by, #{glueSpanSetting.updateTime,jdbcType=TIMESTAMP} update_time, #{glueSpanSetting.delFlag,jdbcType=VARCHAR} del_flag, #{glueSpanSetting.remark,jdbcType=VARCHAR} remark
) x
